from pathlib import Path
import base64, gzip

ROOT = Path(__file__).resolve().parents[3]
OUT = ROOT / 'pine-script' / 'master-smc-sats-nci-story' / '03_SCRIPT_BLOCKS' / '00_ict_validated_smc_source_full.pine'

CHUNKS = [
"",
"",
"",
"",
"",
"",
"",
""
]

OUT.parent.mkdir(parents=True, exist_ok=True)
OUT.write_bytes(gzip.decompress(base64.b64decode(''.join(CHUNKS))))
text = OUT.read_text(encoding='utf-8')
required = ['//@version=6', 'type OTEZone', 'type BPR', 'type IFVG', 'type BreakerBlock', 'alertcondition(longSignal']
for item in required:
    if item not in text:
        raise RuntimeError('Missing ICT source check: ' + item)
print('Restored', OUT.relative_to(ROOT), 'lines', len(text.splitlines()))
